import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.BvlN9b-o.js";const c=JSON.parse('{"title":"10 部署、观测并恢复自己的工单业务","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/learn/production","contentType":"tutorial","prev":{"text":"09 HTTP 验证与 SDK","link":"/learn/verification"},"next":false},"headers":[],"relativePath":"learn/production.md","filePath":"learn/production.md"}'),n={name:"learn/production.md"};function p(h,s,l,r,o,k){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="_10-部署、观测并恢复自己的工单业务" tabindex="-1">10 部署、观测并恢复自己的工单业务 <a class="header-anchor" href="#_10-部署、观测并恢复自己的工单业务" aria-label="Permalink to &quot;10 部署、观测并恢复自己的工单业务&quot;">​</a></h1><p>起点：<code>jobs</code> 检查点和第九课的公开检查。把同一份模块带到生产，目标是证明工单、文件和排队任务真实可恢复，不是只让健康接口返回 200。</p><p>前提是单机 Docker 主机、可访问 TLS 域名、生产配置和已经审阅的源码。下面在课程副本根目录执行，生产步骤会创建持久数据与开放入口；先完整阅读<a href="./../tutorials/single-machine-production">生产部署指南</a>。</p><h2 id="确认自己的业务已组装" tabindex="-1">确认自己的业务已组装 <a class="header-anchor" href="#确认自己的业务已组装" aria-label="Permalink to &quot;确认自己的业务已组装&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> boundaries:check</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --locked</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saas-api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> saas-worker</span></span></code></pre></div><p>API 的两条 Router 路径和 OpenAPI 必须含 tickets，Worker 必须注册工单导出 Handler，以及 Core 文件清理/维护与业务导出期限维护。默认模板未注册工单，不能在原模板直接构建并期待课程接口出现。</p><p>把这份副本中的业务变更保存到自己的源码版本；课程 <code>.env</code>、Cookie 与下载产物都是本地开发数据，不复制进生产密钥配置。</p><h2 id="构建与显式迁移" tabindex="-1">构建与显式迁移 <a class="header-anchor" href="#构建与显式迁移" aria-label="Permalink to &quot;构建与显式迁移&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/production/env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>填写真实 DOMAIN、Origin、数据库/存储密钥；启用邮件时 API/Worker 使用相同加密 key。构建嵌入包含工单表的迁移集合；启动顺序是依赖健康 → migrate → storage-init → API/Worker/Caddy。不要用 API 启动隐式补 schema。</p><p>将请求终端的 <code>BASE_URL</code> / <code>ORIGIN</code> 改为这个 HTTPS 入口，然后重新执行第二课注册/创建和第七课上传下载，生成这次生产演练的数据。开发副本的数据不会因部署源码自动迁移进生产卷。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/ready&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -b</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .scratch/course-http/cookies</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$BASE_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/api/v1/tickets/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TICKET_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>预期 readiness 与工单读取 200，TLS 入口与授权规则一致。迁移不匹配时 readiness 503，应核对当前镜像、迁移与数据库，再显式迁移。</p><h2 id="关联请求、任务和持久事实" tabindex="-1">关联请求、任务和持久事实 <a class="header-anchor" href="#关联请求、任务和持久事实" aria-label="Permalink to &quot;关联请求、任务和持久事实&quot;">​</a></h2><p>保留创建/导出响应的 request_id，查询工单、Core Job 和审计。当前 tracing/Jobs/Audit 接线会关联请求与每次 Worker attempt；请求结束后任务也有自己的 span。产物和通知可查询才证明提交，看到 trace 不等于成功。</p><p>需要本地观测组合时在开发环境运行 <code>just dev-observability</code>，按<a href="./../tutorials/observability">观测指南</a>查日志、队列和存储操作；新增业务无需让 Domain 依赖 OTel。已有观测服务占端口时先配置空闲观测端口。日志不保存正文、Cookie、密码或完整签名 URL，资源 id 不作为高基数 metric label。</p><p>Redis 或遥测失联不改变工单持久状态。Worker 暂停时导出请求可以排队，恢复后继续领取；自己的任务依然必须尊重租约、取消与发布时重新授权。</p><h2 id="备份与独立恢复" tabindex="-1">备份与独立恢复 <a class="header-anchor" href="#备份与独立恢复" aria-label="Permalink to &quot;备份与独立恢复&quot;">​</a></h2><p>在原模板根目录可先运行工单专用的本地演练：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tutorial:recovery:check</span></span></code></pre></div><p>它要求本地 Docker 及空闲的 80/443，创建独立课程副本、镜像和两个生产 Compose 项目，通过 localhost TLS 执行真实工单创建/更新、附件上传、停 Worker 入队、备份和独立恢复。恢复后比对工单字段/版本、附件字节、JSON 导出和终态通知；结束清理自己创建的项目、卷与私有临时数据，只保留脱敏报告。它验证课程业务的本地交付与恢复，自己的公网域名和生产主机仍按下面的步骤验收。完整入口见<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/scripts/check-tutorial-recovery.mjs" target="_blank" rel="noreferrer">工单恢复演练</a>。</p><p>按<a href="./../tutorials/backup-restore">备份指南</a>进入维护窗口，先 drain API 再 Worker：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-backup</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/ticket-course</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backups/ticket-course</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span></code></pre></div><p>检查 backup/restore 报告 PASS，生产卷保留，恢复项目使用新网络与新卷。归档包含业务 schema 和 Files ready 对象，不包含密钥；准备归档对应镜像和受保护配置，不把新迁移强行应用到历史恢复库。</p><p>恢复后再请求同一个生产 <code>TICKET_ID</code>，比对字段/版本；按第七课下载附件比对 sha256；备份前排队的导出应由恢复 Worker 完成。pending 上传按 TTL 处理，1 小时导出到期后停止签下载并由业务维护回收。</p><p>框架 <code>production-smoke</code> / <code>production-restore-drill</code> 默认验证知识库旅程，不会自动断言工单。自己的上述恢复结果必须单独记录；健康或清单通过不能替代业务旅程。任何流量切换都显式决定，不能用删除生产卷解决端口冲突。</p><p>上一课：<a href="./verification">公开验证与 SDK</a>。课程完成后，从<a href="./../docs/">能力指南</a>继续加入自己的业务规则和独立交付检查。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/learn/10-production.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,29)])])}const F=a(n,[["render",p]]);export{c as __pageData,F as default};
